WITH ranked AS (SELECT id,ROW_NUMBER() OVER (PARTITION BY lower(trim(name)),category ORDER BY datetime(created_at) DESC,id DESC) AS rn FROM places WHERE lower(trim(name)) IN ('tiny wee gallery','st olaf house','st paul’s church, covent garden','all souls langham place','st giles-in-the-fields','christ church spitalfields','pollock’s toy museum, leadenhall market','the household cavalry museum','banqueting house','the courtauld gallery','charterhouse square','london fields','duck pond market richmond','severndroog castle producers market','south kensington farmers’ market','marylebone farmers’ market','portobello road market','brockwell park viewpoint','the terrace at one leadenhall')) UPDATE places SET status='archived',updated_at=CURRENT_TIMESTAMP WHERE id IN (SELECT id FROM ranked WHERE rn>1);

UPDATE app_meta SET value=CAST(CAST(value AS INTEGER)+1 AS TEXT),updated_at=CURRENT_TIMESTAMP WHERE key='data_version';
